import { can, routeAccess, type Actor, type Permission } from '../authorization';

export const helpGroups = ['Getting Started', 'Sales', 'Sales Management', 'Support', 'Marketing', 'Administration'] as const;
type HelpSection = { heading: string; paragraphs: string[]; permission?: Permission };
type HelpTopic = { title: string; summary: string; group: typeof helpGroups[number]; permission?: Permission; accessPath?: string; sections: HelpSection[] };

// User guidance only. Operational and maintainer notes belong in app/docs.
export const helpTopics = {
  'getting-started': {
    title: 'Getting started', group: 'Getting Started', summary: 'Find your way around SalesHub and pick up where you left off.',
    sections: [
      { heading: 'What SalesHub is for', paragraphs: ["Keep customer relationships, deals, follow-up work, and Support Cases in one place. Before a customer call, check the Account for recent conversations, open work, and the people involved.", "Start with your Dashboard. Its contents depend on your role and any layout you’ve saved. The side menu shows the areas you can access; on a phone or tablet, open the menu button to see them."] },
      { heading: 'Search and Recent Items', paragraphs: ["Use Search when you know what you’re looking for. Recent Items is faster when you want to get back to something you were just working on. Both are in the header and only show records you can access."] },
      { heading: 'New and Quick Actions', permission: 'support-work.write', paragraphs: ["Use New in the header to start a record where that option is available. On a customer or deal page, Quick Actions save time by filling in the relationships already known from that page. Review the details before saving. Support Case work starts from the Case’s own actions."] },
      { heading: 'Notifications', paragraphs: ["Open the bell to review assignments and follow-ups that need attention. Open a notification to check the record before acting. You can adjust notification preferences or snooze optional categories; Critical alerts stay on."] },
      { heading: 'My Day', paragraphs: ["Use My Day from the Dashboard to review meetings, completed Activities, and Tasks for a chosen date. Calendar details depend on your connection. Connecting Calendar doesn’t automatically log meetings as Activities."] },
      { heading: 'Your access', paragraphs: ["If you can open a record but don’t see an edit or create action, your role may only have viewing access. Ask an Admin if you need different access for your work."] },
    ],
  },
  'accounts-contacts': {
    title: 'Accounts & Contacts', group: 'Getting Started', summary: 'Keep companies, people, and their relationships clear.', permission: 'accounts.read',
    sections: [
      { heading: 'Company or person?', paragraphs: ["An Account represents an organization you work with, such as a distributor, reseller, OEM, or end customer. A Contact represents a person, such as the buyer at a reseller or the technician testing a printer.", "Relationships help the next person understand who’s involved. A deal may include a distributor, a reseller, and an end customer. Link the right companies and people so conversations and follow-up work are easy to find."] },
      { heading: 'Shared customer information', paragraphs: ["SalesHub lets the sales team see shared customer and opportunity information so reps can collaborate and cover for one another. Sales users can view other Sales reps’ Accounts, Opportunities, and Projects. The owner is the person responsible for keeping the record current; ownership doesn’t limit Sales viewing to that person’s records.", "Viewing a colleague’s records doesn’t give you extra editing or reassignment rights. It also doesn’t share or transfer revenue, commission, or forecast ownership."] },
      { heading: 'Before adding someone', paragraphs: ["Search by company name and the person’s name or email first. Check spelling variations and existing Account relationships before assuming someone is missing."] },
      { heading: 'Create a Contact', permission: 'contacts.write', paragraphs: ["Create a Contact when you have a new person to work with and no existing Contact matches. Link their Account when you know it. If their company is unclear, verify it before linking them to a similar name. Use the existing Contact when the same person is involved in another deal."] },
    ],
  },
  'activities-tasks': {
    title: 'Activities & Tasks', group: 'Getting Started', summary: 'Record what happened and keep the next step separate.',
    sections: [
      { heading: 'Happened or still to do?', paragraphs: ["Activity = something that happened. Task = something that still needs to happen. After a printer demo, record the demo as an Activity. If you promised to send setup instructions tomorrow, create a Task.", "A Note is background or working information. Use a Task when someone needs to do something; a Note alone won’t track that work."] },
      { heading: 'Rolling Task due dates', paragraphs: ["Task due-date filters use Eastern business dates. Overdue means before today; Due today means today. Next 7 days includes today through seven calendar days from today. This week means Monday through Sunday. These periods leave out Tasks without a due date and completed Tasks, unless you explicitly choose Status Completed. Custom date / range keeps fixed dates; use the same From and Through date for one exact day.", "Combine an Assignee with a due-date period to save a personal view. A Saved View for My Overdue Tasks will continue to show whatever is overdue whenever you open it."] },
      { heading: 'Choose an Activity type', paragraphs: ["Call: a completed phone or voice conversation. Email: a message already sent or received. Meeting: a meeting that has taken place. Demo: a completed product demonstration.", "Technical Review: a technical discussion, such as firmware or integration requirements. Site Visit: a visit to a customer location. Trade Show / Event: a conversation at an event; the standard choice is Trade Show. Other: an interaction that doesn’t fit a more specific choice.", "You may also see active choices such as Quote / Proposal, Sample / Evaluation, or Follow-up. A Follow-up Activity still records a completed interaction. Retired or deactivated types may appear on historical records; use an active choice for new work."] },
      { heading: 'Make the next handoff easy', permission: 'support-work.write', paragraphs: ["Write a short subject and enough detail for a colleague to understand the outcome. Check the occurrence date and the time zone shown in the form. Put future work in a Task with an assignee and a due date.", "A follow-up date on an Activity is a reference date. When creating an Activity, select Create follow-up task if you also want a Task. Completing a Task doesn’t automatically record an Activity."] },
      { heading: 'Check the relationships', permission: 'support-work.write', paragraphs: ["Quick Actions fill in known Account, Contact, Opportunity, Project, or Case details. If several Accounts could apply, you may need to choose one. Check those links before saving so the work appears with the right customer.", "For Support work, start from the Case so its customer details carry through."] },
      { heading: 'Calendar meetings', permission: 'sales.read', paragraphs: ["For a synced meeting, use Calendar Matches to log it once rather than also entering it manually."] },
    ],
  },
  'saved-views': {
    title: 'Saved Views', group: 'Getting Started', summary: 'Return to the list filters you use most often.',
    sections: [
      { heading: 'Save a useful starting point', paragraphs: ["On lists with Saved Views, set your filters and save the view with a name you’ll recognize, such as ‘My open deals’. Views are personal. They don’t give you access to extra records.", "Make a view the default if you want it applied when opening that list without other filters. Changing filters marks the view Modified; it doesn’t replace your saved settings. Use Manage views to rename, delete, or change the default."] },
      { heading: 'Check dates when you return', paragraphs: ["A saved calendar date stays fixed. On Opportunities, Current Quarter and Next Quarter move with the calendar; a named quarter or custom date range stays fixed. Saved Views keep list filters, while saved reports keep a report’s setup."] },
    ],
  },
  'reports-dashboards': {
    title: 'Reports & Dashboards', group: 'Getting Started', summary: 'Start with your role’s overview, then narrow the question.',
    sections: [
      { heading: 'Start with your Dashboard', paragraphs: ["Sales usually starts with personal deals and follow-ups. Sales managers see team summaries. Support focuses on Cases and follow-ups; Marketing has campaign and event information. Admin and Read Only have their own starting views. Your saved layout can change what appears."] },
      { heading: 'Use filters deliberately', paragraphs: ["Open Reports for a closer look at the reports available to your role. Check the date range, owner, status, and currency before comparing numbers. A filtered list or report may answer a different question from a Dashboard card.", "Use Saved Views for a repeatable list of records. Use a saved report when you need the same report setup again. When snapshot comparisons are available to your role, use them to compare earlier points in time rather than today’s changing records."] },
    ],
  },
  opportunities: {
    title: 'Opportunities', group: 'Sales', summary: 'Keep a real potential sale current enough for the next conversation.', permission: 'opportunities.read',
    sections: [
      { heading: 'What belongs here', paragraphs: ["Use an Opportunity for a potential sale you’re actively working, such as a reseller’s planned printer deployment. Link the participating Accounts and Contacts so the customer, channel partners, and people involved are clear.", "Stage says where the deal is in the sales process. Expected Close Date is your current estimate of when it will close. Owner is the person responsible for keeping it current. Forecast Category says how confidently it belongs in the forecast; stage alone doesn’t make a deal Commit."] },
      { heading: 'Viewing and ownership', paragraphs: ["Sales users can view other Sales reps’ Accounts, Opportunities, and Projects to collaborate and cover for one another. The owner remains responsible for the record. Viewing another rep’s deal doesn’t change who can edit or reassign it, or who receives revenue, commission, or forecast attribution."] },
      { heading: 'Expected Close Date and Actual Close Date', paragraphs: ["Expected Close Date is when Sales currently expects the Opportunity to close. It is part of forecasting and may change as the deal progresses. Actual Close Date is when the Opportunity actually closed, whether Won or Lost. Actual Close Date and Outcome Reason are required for a new Won or Lost closure. Closing a deal keeps the actual and expected dates separate.", "For example, an Opportunity expected to close December 15 but actually closed January 8 keeps December 15 as its Expected Close Date and January 8 as its Actual Close Date. Recording the actual date doesn’t replace the forecasted date.", "Some older closed Opportunities show Unknown for the actual date or reason. Those details haven’t been recorded. An Expected Close Date doesn’t confirm when a deal actually closed. When a deal is reopened, earlier close details remain in Opportunity History instead of appearing as its current outcome."] },
      { heading: 'Closing an Opportunity', permission: 'sales.write', paragraphs: ["Choose a Closed Won or Closed Lost stage, then enter the Actual Close Date and choose an Outcome Reason before saving. SalesHub suggests the current New York business date for a new closure; change it if the deal closed on another date. Outcome Notes are optional.", "The reason choices match the result. Closed Won might use Existing customer expansion; Closed Lost might use Lost to competitor or Price. Admins manage the available reasons. A reason selected earlier stays readable in the deal and its history if the choice is later renamed or deactivated."] },
      { heading: 'Outcome Reasons and Outcome Notes', paragraphs: ["The Outcome Reason gives a consistent explanation for a win or loss. The choices depend on whether the Opportunity was Won or Lost. Outcome Notes add optional short context when the reason doesn’t tell the whole story.", "A sentence or two is enough: ‘Customer selected a competitor because of an existing corporate standard.’ ‘Project moved to the next fiscal year.’ ‘Customer expanded an existing deployment to another 40 locations.’ There’s no need for a long narrative."] },
      { heading: 'Reopening an Opportunity', permission: 'sales.write', paragraphs: ["When you have permission to change the stage, you can reopen a closed Opportunity by moving it to an open stage and saving. Its current Actual Close Date, Outcome Reason, and Outcome Notes are cleared because the deal is open again. The previous close event and its details remain in Opportunity History.", "If the deal closes again later, enter a fresh Actual Close Date and Outcome Reason, with optional new Outcome Notes. Reopening doesn’t replace the Expected Close Date; keep that forecast date current as the deal progresses."] },
      { heading: 'Find closed deals', paragraphs: ["On the Opportunities list, open Filters → Outcome filters to choose Won, Lost, or Open, an Actual Close Date range, or an Outcome Reason. Expected Close Period filters planned timing; Actual Close Date filters when the deal closed. Both apply when selected. For Lost this quarter by actual timing, choose All dates for Expected Close Period and enter the quarter’s Actual Close Date range.", "Inactive reasons remain available for older deals; record labels stay as originally saved. Older closures with no Actual Close Date show Not recorded and are excluded by an actual-date range. Saved Views retain outcome filters along with your search, owner, and other criteria."] },
      { heading: 'Why outcome information matters', paragraphs: ["Consistent dates and reasons help the team understand why deals are won or lost and spot recurring sales patterns. Sales, Sales Managers, and Admins can review Pipeline Movement → History & Outcomes for recorded outcomes, reasons, and expected versus actual close timing. These results do not provide a forecast-accuracy score or establish booked revenue."] },
      { heading: 'Products and estimated value', paragraphs: ["Opportunity value comes from the products’ quantities and estimated unit prices. Keep those lines current as scope changes. Check SKU, quantity, currency, and pricing source before relying on the total."] },
      { heading: 'Customer Context', paragraphs: ["Record the customer’s current product, competitor, pricing information, and pain points when you know them. For example: ‘Replacing older desktop printers; needs faster label changes.’ Keep it useful for the next customer conversation."] },
      { heading: 'Before a forecast review', permission: 'sales.write', paragraphs: ["Update stage, Expected Close Date, products, owner, and Forecast Category together. If an open deal moves into next quarter, update its Expected Close Date to reflect the new forecast."] },
    ],
  },
  projects: {
    title: 'Projects', group: 'Sales', summary: 'Keep the broader customer initiative, participating companies, and progress together.', permission: 'projects.read',
    sections: [
      { heading: 'When to use a Project', paragraphs: ["A Project represents a broader customer initiative or deployment involving several people, Activities, important target points, and possibly several Opportunities. An Opportunity is a specific potential sale or revenue event within that work. An Opportunity can stand on its own; it doesn’t need a Project.", "For example, a national rollout Project may have separate Opportunities for printers, accessories, or phases of deployment. The Project keeps the overall initiative understandable while each Opportunity carries its own products, value, forecast, and outcome."] },
      { heading: 'Accounts and participants', paragraphs: ["Primary Account is optional. It identifies the company primarily responsible for the Project, with a role such as Program Owner or End Customer. A Project can start before that company is confirmed. Keep the customer context clear in the description and connect the appropriate Accounts when known.", "Additional Participants are participating Accounts, each with one or more roles specific to this Project, such as Distributor, Integrator, or Implementation Partner. They help explain how several customer organizations or partners are involved. The Primary Account appears separately from Additional Participants.", "Individual people are Contacts on their Accounts or Opportunities. The Project’s Participants tab lists companies and their Project roles; it isn’t a separate list of individual stakeholders."] },
      { heading: 'Linked Opportunities', paragraphs: ["The Opportunities tab shows sales opportunities connected to the initiative. One Project may have several linked Opportunities, and an Opportunity can be linked to more than one Project when appropriate. Linking them keeps the broader work and the individual sales pursuits easy to follow.", "Project ownership and Opportunity ownership remain separate. A link doesn’t move the Opportunity’s revenue, commission, or forecast attribution to the Project owner."] },
      { heading: 'Updates and milestones', paragraphs: ["Project Updates capture progress and context: what changed, what is blocked, or what the team agreed next. An update can also refer to a linked Opportunity, so the same context can be read from both records.", "A milestone is an important target point or event, such as evaluation sign-off or the first rollout site. Keep these target points in the description and Project Updates. Start date and Target end date describe the overall schedule; Tasks track individual actions and due dates. Projects don’t currently have a separate milestone tracker."] },
      { heading: 'Keeping the Project current', permission: 'projects.write', paragraphs: ["Keep the owner, status, description, and dates current as the initiative develops. Use Add update on the Project Updates tab for a short progress entry. When an update also concerns a linked Opportunity, choose it in Linked Opportunity if you have permission to update both records.", "Add the participating Accounts and their Project roles when you know who is involved. Link an Opportunity when it belongs to this initiative and you have permission to make that change."] },
      { heading: 'Ownership and shared visibility', paragraphs: ["Sales users can view Projects owned by other Sales reps, just as they can view colleagues’ Accounts and Opportunities. This helps the team collaborate and cover for one another. The owner still identifies who is responsible. Existing editing and reassignment permissions continue to apply."] },
      { heading: 'Keep each record useful', paragraphs: ["Use Tasks for actions still to do, Opportunities for specific sales pursuits, and Accounts for organizations. Keep completed calls, meetings, and other interactions in Activity history. A Project brings the initiative together without replacing those records."] },
    ],
  },
  'forecast-categories': {
    title: 'Forecast Category', group: 'Sales', summary: 'Choose the confidence level that matches the deal today.', permission: 'opportunities.read',
    sections: [
      { heading: 'The choices', paragraphs: ["Pipeline: a developing deal. Best Case: a deal that could close in the period if things go well. Commit: a deal you’re explicitly putting in your committed forecast. Agree that judgment with your manager; SalesHub doesn’t infer Commit from stage.", "Omitted: keep the Opportunity, but leave it out of the open forecast. A won stage sets the category to Closed; a lost stage sets it to Omitted."] },
      { heading: 'How the totals work', paragraphs: ["In forecast reports, the Pipeline total includes open deals in Pipeline, Best Case, and Commit. Best Case and Commit are also shown separately. Don’t add those three displayed totals together: Best Case and Commit are already inside Pipeline. Closed Won is separate."] },
    ],
  },
  forecasting: {
    title: 'Forecasting', group: 'Sales', summary: 'Use My pipeline, choose a salesperson, and read forecast totals correctly.', permission: 'sales.read',
    sections: [
      { heading: 'My pipeline and salesperson filters', paragraphs: ["For a Sales user, Pipeline defaults to My pipeline. Its Opportunities and totals initially represent your own open pipeline. The Owner filter shows My pipeline until you choose a person; other filters can narrow the result further. The Pipeline page includes open Omitted deals. Its date filters use Expected Close Date.", "To cover for a colleague or review their deals, choose another eligible salesperson in Owner and select Apply. To clear that salesperson selection, set Owner to My pipeline and select Apply. You’ll return to your own deals while keeping the other filters.", "Viewing another rep’s pipeline doesn’t change record ownership, revenue attribution, commission attribution, or forecast ownership. It is a different view of the team’s shared information.", "A Saved View can reopen a salesperson filter you deliberately saved. If you made it your default, opening Pipeline or selecting Clear can apply that view again. Set Owner to My pipeline and select Apply when you want your own deals."] },
      { heading: 'Read the forecast', paragraphs: ["In the forecast report, Pipeline includes open deals marked Pipeline, Best Case, or Commit. Best Case and Commit use full deal values without a probability adjustment. Omitted and closed deals don’t contribute to that open forecast total. Weighted Pipeline applies the deal’s probability. The standalone Pipeline page also includes open Omitted deals, so check the page and filters before comparing totals.", "Team forecast totals include active Sales and Sales Manager owners. Check owner, Expected Close Date, and the selected period when a deal appears to be missing. Values come from current product quantities and estimated unit prices."] },
      { heading: 'Two kinds of forecast history', paragraphs: ["Forecast Snapshot History compares quarterly forecasts from Opportunity Snapshots captured at a point in time. Forecast Movement compares separate weekly captures, including targets and Weighted Pipeline. Creating either kind does not create the other."] },
      { heading: 'Keep currencies separate', paragraphs: ["SalesHub uses the company’s configured currency. With one active currency, unnecessary currency controls are hidden. With multiple active currencies, relevant views offer a currency selection and keep totals separate. SalesHub does not convert currencies automatically."] },
      { heading: 'Closed Won and history', paragraphs: ["In Forecast Snapshot History, Closed Won means deals in a won stage at capture, placed in a quarter by Expected Close Date. Actual Close Date records when the deal actually closed; it doesn’t change those saved forecast totals. Closed Won in this view isn’t booked or recognized revenue.", "Opportunity snapshots preserve what the pipeline looked like at a point in time so you can compare how deals moved later. Forecast snapshots preserve forecast totals for a point in time so managers can compare what changed week to week. Opportunity and Forecast Snapshot History reports are available to Sales Managers and Admins. Pipeline Movement is also available to Sales."] },
    ],
  },
  'price-exceptions': {
    title: 'Price Exceptions', group: 'Sales', summary: 'Check approved special pricing and follow up before it expires.', permission: 'pricing.read',
    sections: [
      { heading: 'When to use one', paragraphs: ["A Price Exception records special approved pricing for particular customers and products. Use Price Exception lookup when checking whether special pricing is available, even before you have an Opportunity.", "Check the linked customer, SKU, approved price, currency, and minimum quantity. Different tiers may apply at different quantities. A similar product name or customer name isn’t enough to confirm the price applies."] },
      { heading: 'Using it on a deal', paragraphs: ["Where applicable, select PE pricing on the Opportunity product line and check that the participating Account and quantity match. The Opportunity’s actual unit price determines its value; the PE approved price is also available for reference."] },
      { heading: 'Expiration and follow-up', paragraphs: ["Check the expiration date before using a price. A PE can still have an Active status even though its date has passed; the date and stored status are separate. Follow-up status tracks renewal work, not whether a price is valid.", "Use the expiring PE report to review upcoming renewals. Availability and follow-up actions depend on your access and which PEs are assigned to you."] },
    ],
  },
  'opportunity-snapshots': {
    title: 'Opportunity Snapshots', group: 'Sales Management', summary: 'Compare deals as they looked at two earlier points in time.', accessPath: '/reports/opportunity-snapshots',
    sections: [
      { heading: 'Why use a snapshot?', paragraphs: ["Opportunity snapshots preserve what the pipeline looked like at a point in time so you can compare how deals moved later. Use Opportunity Snapshot History to compare dates, then narrow by owner, stage, category, or currency.", "Review changes in value, stage, owner, and Expected Close Date. A deal entering or leaving a snapshot isn’t automatically a win or loss; changed dates, relationships, or archive state can also affect what’s included. Keep currencies separate."] },
      { heading: 'Capturing a snapshot', permission: 'users.manage', paragraphs: ["Admins capture snapshots in Administration. The default includes open, unarchived Opportunities with eligible Accounts and Projects, including Omitted deals and deals without an owner or close date. Select Include forecast data if you’ll need Forecast Snapshots; it also includes Closed Won deals. Archive known test records before capturing; they aren’t filtered out automatically.", "Preview and review before confirming. Only one capture is available per calendar week, Monday–Sunday in New York time. You can’t replace that capture or add the forecast option afterward. When configured, weekly automation captures forecast-ready history on Monday at 5 a.m. New York time. Admins can see execution status on the snapshot pages; manual capture is still available."] },
    ],
  },
  'pipeline-movement': {
    title: 'Pipeline Movement', group: 'Sales', summary: 'Explain weekly pipeline movement, historical progression and deal outcomes.', accessPath: '/reports/pipeline-movement',
    sections: [
      { heading: 'Choose the question', paragraphs: ["Use Weekly Comparison to explain the change between two saved weeks. Use History & Outcomes to follow several weeks, then review what happened to deals in an earlier forecast. Use Opportunity Snapshot History for saved deal details and Forecast Snapshot History for quarterly totals when those reports are available to your role.", "For example, if a $200,000 deal moves out of the selected quarter, pipeline falls by $200,000. If its value also falls to $150,000, that $50,000 change is shown in the details and is not deducted again. Each deal contributes once to the change in pipeline."] },
      { heading: 'Choose two snapshots', paragraphs: ["Open Pipeline Movement from Reports or Quarterly Forecast. It compares two complete weekly Opportunity Snapshots whose saved values do not change. The default is the latest valid capture and its immediately prior capture, using the later capture’s calendar quarter. If no prior capture exists, movement is unavailable. Manual and automated captures are both supported.", "Sales starts with your own pipeline. Intentionally choose another eligible salesperson to view their movement. Managers and Admins can also select all eligible reps. Viewing a colleague does not change ownership, revenue, commission or forecast attribution. When multiple currencies are configured, choose a currency; unlike currencies are never combined."] },
      { heading: 'Multi-week trends and quarter progression', paragraphs: ["Pipeline Movement has two views: Weekly Comparison and History & Outcomes. Use the view switcher to move between them. Both views share this Help topic; quarter, salesperson and currency filters carry between views.", "The main filters stay visible; expand Advanced filters for Account, forecast category at the reference date, reference snapshot, Show outcomes, Outcome reason and quarter comparison. Choose 4, 8 or 12 weeks, or the full selected quarter. The window ends at the latest available capture in that quarter. Starting values use the first available capture in the window. The chart and table show Pipeline (including Best Case and Commit), category values and captured Closed Won. These values describe the saved snapshots; they do not predict future results.", "Missing weeks break chart lines and remain missing. Closed Won is the cumulative value present in each snapshot, assigned by captured Expected Close Date; weekly totals are never added together. Legacy open-only captures cannot establish Closed Won. Slipped and new/entered movement sum adjacent snapshot comparisons from the baseline, using the same reconciliation as Weekly Comparison. Repeated exits and entries count as separate observed movements."] },
      { heading: 'Forecast Outcome Analysis', paragraphs: ["Choose Commit, Best Case or all open categories and a reference snapshot. The default looks for a snapshot on or within seven days before the point four weeks before quarter end. If none exists, select an available capture. The selected deals keep the owner, Account, category, currency and amount saved in the reference snapshot. Outcomes describe what ultimately happened: Won in-period, Won later or earlier, Lost, slipped to another quarter, still open or unknown.", "The current Opportunity record determines one outcome per deal. Prior closure and reopen events, including archived history, remain context. An open reopened Opportunity is still open; its prior win is not counted again. A disagreement between current state and recorded outcome history is flagged for review. Outcome history may be incomplete for legacy records. This follows the selected deals over time, without salesperson scores or rankings."] },
      { heading: 'Expected vs Actual Close', paragraphs: ["The outcome table compares the snapshot’s Expected Close Date with the latest recorded Actual Close Date by calendar quarter. Closed in the same quarter means closed in the expected period; an earlier or later quarter is shown explicitly. Open deals with a date in another quarter show slipped to another quarter. Actual close unknown means a closed legacy Opportunity has no Actual Close Date; no date is inferred from stage changes or history timestamps. Actual results never rewrite historical captures."] },
      { heading: 'Slippage detail', paragraphs: ["Slippage lists each deal once at its first observed exit from the selected quarter in the chosen window. Value and Forecast Category come from immediately before that exit. Weeks moved is the signed Expected Close Date difference rounded up to weeks; a cleared date stays unknown, and movement to an earlier quarter is labeled. Current/actual quarter uses current Expected Close Date for open deals and Actual Close Date for closed deals. Summary counts use one latest outcome per Opportunity. Cumulative movement can exceed the distinct first-slip total when a deal exits more than once."] },
      { heading: 'Won and Lost reasons', paragraphs: ["Reason views use each deal’s first in-scope observation in the selected window and its latest recorded outcome reason label. Inactive and renamed historical labels are retained. Filter to Won, Lost, Lost after an observed Commit, or Lost after an observed slip. The last view requires a recorded Actual Close Date on or after the slip observation; unknown dates cannot establish the order. Values are historical deal values, not current bookings. Owner groups are alphabetical; Account groups can overlap when a deal has several participating Accounts."] },
      { heading: 'Quarter comparison and historical dimensions', paragraphs: ["Choose another year and quarter to compare matching relative weeks. At least two weeks must have matching forecast-ready scope versions. Missing periods remain unavailable. Pipeline, Commit and Closed Won use the captured values. Interval slippage requires matching relative starting weeks too. Outcome mixes use distinct observed deals in matched capture weeks. Outcome mixes describe distinct observed deals and current outcomes; quarters can have different follow-up durations.", "Account and owner filters use frozen snapshot membership. Product count was captured, but product family and product line were not, so those historical dimensions are unavailable. Sales defaults to self and can intentionally choose another eligible rep. Managers and Admins can select team totals. Currencies are always separate."] },
      { heading: 'Starting and Ending Pipeline', paragraphs: ["Starting Pipeline is the earlier snapshot’s open Pipeline, Best Case and Commit value for the selected quarter, salesperson and currency. Ending Pipeline uses the same rules on the later snapshot. Explicitly ineligible owners are excluded. Legacy snapshots lack eligibility evidence, so their captured owners are included without using current user settings.", "Each deal contributes its ending in-scope value minus its starting in-scope value exactly once. The signed reconciliation rows explain the change. Owner transfers, currency changes, category exclusions, restored scope and reopenings appear in scope entry or exit rows."] },
      { heading: 'Slipped, entered and value changes', paragraphs: ["Slipped means a deal’s Expected Close Date left the selected quarter, including a cleared date. Entered means it moved into the quarter. A deal that slips out at $200K and falls to $150K contributes −$200K to that quarter. Its $50K value decrease remains in All changes and is not deducted again. Deals remaining in scope contribute only their value increase or decrease."] },
      { heading: 'Forecast composition', paragraphs: ["A $100K deal moving Best Case → Commit changes forecast composition but does not change total pipeline. It shows $100K out of Best Case, $100K into Commit and $0 Pipeline Impact.", "For each category: previous value + moved in − moved out + retained-deal value changes = current value. Entry and exit amounts use the captured endpoint value and can also reflect changes in period, salesperson, currency or eligibility."] },
      { heading: 'Closed Won, Lost and removal', paragraphs: ["A captured transition to Won or Lost removes the earlier open value. Existing weekly captures include Won but exclude Lost; older captures include only open deals. Absence is shown as removed with reason not recorded, never assumed Lost. Newly included deals are not necessarily newly created. A newly captured Won or Lost deal without an earlier open value shows zero Pipeline Impact. Actual Close Date and Outcome Reasons do not rewrite captured history."] },
      { heading: 'Find the Opportunities', paragraphs: ["Use the compact management groups or Deal movement table to open an Opportunity. All changes expands the previous and current dates, categories, stages and every detected change. Primary Movement is a deterministic label; additional changes remain visible. Group lists can overlap and are not additive. The reconciliation allocates each deal only once.", "Primary precedence is Won, Lost, slipped out, entered, new, removed, reopened, value decrease or increase, forecast downgrade or upgrade, stage regression or advancement, then other changes. Stage direction uses captured stage probability because stage sort order was not captured. Equal probabilities show Stage changed."] },
    ],
  },
  'forecast-snapshots': {
    title: 'Forecast Snapshots', group: 'Sales Management', summary: 'Compare quarterly forecast totals and trace changes back to deals.', accessPath: '/reports/forecast-snapshots',
    sections: [
      { heading: 'Compare the same quarter', paragraphs: ["Forecast Snapshot History uses Opportunity Snapshots to preserve quarterly forecast totals at their capture time. Forecast Movement uses separate weekly captures; creating one kind does not create the other. In Forecast Snapshot History, choose the forecast year and quarter, then two capture dates. Narrow by salesperson or currency when useful.", "Pipeline includes Best Case and Commit. Closed Won uses the captured won stage and Expected Close Date. Actual Close Date doesn’t move deals between the saved forecast quarters. Currencies remain separate. Explain movement opens the Opportunity comparison behind the change.", "Opportunity counts include open forecast deals and won deals. A missing snapshot means there’s no saved history for that selection. It doesn’t mean the forecast was zero. When the earlier value is zero, a percentage change isn’t shown."] },
      { heading: 'Creating the totals', permission: 'users.manage', paragraphs: ["First capture an Opportunity Snapshot with Include forecast data selected. In Administration → Forecast Snapshots, choose that capture and the quarter, preview the totals, then confirm. Older open-only captures can’t be used for this.", "There’s one Forecast Snapshot per Opportunity capture and quarter. Its point in time comes from the Opportunity capture, even if you create the totals later. Only eligible Sales and Sales Manager owners with deals dated in that quarter contribute. When configured, weekly automation captures the quarter at the source’s capture time. Admins can still capture other quarters manually."] },
    ],
  },
  'support-cases': {
    title: 'Support Cases', group: 'Support', summary: 'Keep the customer issue, responsibility, and next step together.', permission: 'support-cases.read',
    sections: [
      { heading: 'What belongs in a Case', paragraphs: ["Gmail is the system of record for email. SalesHub is the system of record for the Support Case.", "Use a Case for a customer issue that needs investigation, a response, or follow-up, such as a printer setup problem. Keep the problem and resolution understandable to the next Support rep. Link the customer Account and Contact when you can identify them confidently."] },
      { heading: 'Working the Case', permission: 'support-cases.write', paragraphs: ["Choose an eligible Support rep or Admin as the assignee so responsibility is clear. Assignment doesn’t prevent another Support rep from helping. Set priority to match urgency and keep status current: New, Open, Waiting on Customer, Waiting on Internal, Resolved, or Closed.", "Use Waiting on Customer or Waiting on Internal to show what’s blocking progress. Record the resolution when the issue is resolved or closed. Set the next follow-up when you need to return to it. Archive is separate from closing a Case."] },
      { heading: 'Notes, Tasks, and history', paragraphs: ["Notes hold troubleshooting details or internal context and can be added directly to a Support Case without a linked Account. Tasks track work still to do, such as checking a firmware result with the customer. Support can edit the subject, description, due date, and status of Case Tasks assigned to them, or unassigned Case Tasks they created, including completing and reopening them. Open a Case Task and choose Edit / complete task. Unrelated Sales Tasks remain outside Support scope. Activities record completed interactions. Adding work doesn’t change Case status.", "The Case page shows recent activity, including linked emails and logged responses. Choose View older history for earlier Notes, Tasks, email activity, and Case changes. History shows newest first; use Next and Previous to move through it. Choose View full note to read a Note without editing it. The Case’s Audit History has more detailed recent recorded changes. Sales, Marketing, and Read Only can review Cases but can’t manage them."] },
      { heading: 'Add work from the Case', permission: 'support-cases.write', paragraphs: ["Start Notes, Tasks, and Activities from the Case actions to carry its customer details through. A Closed or archived Case must be reopened or restored before adding new work; a Resolved Case can still receive follow-up work."] },
    ],
  },
  'support-inbox': {
    title: 'Support Inbox', group: 'Support', summary: 'Decide whether an email needs a new Case, an existing Case, or no action.', permission: 'support-cases.write',
    sections: [
      { heading: 'Start with the request', paragraphs: ["Gmail is the system of record for email. SalesHub is the system of record for the Support Case. Open Support Inbox from Support Cases when the mailbox connection is available. SalesHub shows a bounded recent Gmail batch; the message count shows its limit and lookback. All, Unlinked and Needs Review filter only that current batch. Unlinked has no Case link; Needs Review has an ambiguous or conflicting CRM match still awaiting linking. Ignored messages stay separate. Older mail remains in Gmail.", "Create a Case when the email describes a new customer issue that needs tracking. Link to an existing Case when it continues the same issue. Review suggestions and the BXS Case number before linking; a matching sender alone doesn’t prove it’s the same issue.", "Ignore messages that don’t need a Case, such as routine notices or unrelated mail. Ignore only hides the message from the normal SalesHub inbox view; it doesn’t delete or change anything in Gmail. Show ignored messages to restore one if needed."] },
      { heading: 'Creating a Case from email', paragraphs: ["Review the suggested subject, requester, Account, Contact, and Description / Email Thread. SalesHub carries available email text and quoted history into that description and links the selected email to the Case. It may use the earliest available customer request from the recent conversation to help fill the form.", "Read the description before saving, especially if the newest message is only a short reply. Older messages outside the available window aren’t automatically retrieved as a complete thread. Correct the issue summary and customer links when needed; a new Account or Contact isn’t created automatically."] },
      { heading: 'Choose attachments', paragraphs: ["Select only the files the Case needs, such as a sample label or diagnostic image. Files aren’t imported automatically. Signature and decorative images are hidden initially; review them if a needed file is missing from the first list.", "If a file fails to import, the Case can still be saved. Read the result and use the Case’s email attachment review to retry available files. Keep Gmail for the original message and its full email history."] },
      { heading: 'Linking and replying', paragraphs: ["Link to Existing Case adds email context to that Case. It doesn’t send a response or automatically change the Case’s status. Send replies from Gmail, then use Log Email Response in the Case to leave a short summary."] },
    ],
  },
  'log-email-response': {
    title: 'Log Email Response', group: 'Support', summary: 'Leave a Case history entry after sending your reply from Gmail.', permission: 'support-cases.write',
    sections: [
      { heading: 'Send first, then log', paragraphs: ["SalesHub does not send the email. Send the response from Gmail, then log a short summary in the Case so the Case history shows that you responded.", "Choose Log Email Response on the Case. Check the recipient, subject, and sent time; suggested details may need correcting. Write what you sent and what should happen next, such as ‘Sent the firmware update and asked the customer to retest label alignment.’"] },
      { heading: 'Keep the full email in Gmail', paragraphs: ["The entry is a short record of the interaction. It doesn’t copy your sent email or its attachments from Gmail. Add a file separately to the Case if it belongs with the issue. Reopen or restore a Closed or archived Case before logging a response."] },
    ],
  },
  'trade-shows': {
    title: 'Trade Shows & follow-up', group: 'Marketing', summary: 'Review event leads, check existing relationships, and follow through.', permission: 'trade-shows.read',
    sections: [
      { heading: 'Start with the lead', paragraphs: ["Open the Trade Show to review its leads and the customer’s interests. Check existing Account and Contact matches before creating anyone new. Lead details help the next rep understand the event conversation."] },
      { heading: 'Manage event leads', permission: 'trade-shows.manage', paragraphs: ["Create the Trade Show, import its lead list, and review matches and routing before confirming. Resolve uncertain company and Contact matches rather than guessing from a similar name."] },
      { heading: 'Work the follow-up queue', permission: 'trade-shows.leads.write', paragraphs: ["Open Follow-Up Queue from Trade Shows. Each row shows the latest non-archived linked Task, its status, Task due date and assignee, with Open Task for the next action. No follow-up Task means none is linked. Lead follow-up dates are separate metadata; changing them does not reschedule the Task.", "Use Open, Completed, No follow-up Task, Assigned to me and owner filters to focus your work. Task due periods such as Overdue, Due today and Next 7 days use Eastern time. Save the event, search, owner and Task filters in Saved Views; relative periods roll forward whenever you reopen a view.", "On an event, select leads on the current page and choose Apply Routing. Review the destination and confirm. If a lead changed or a destination is no longer eligible, none of the selected leads change; refresh and review again."] },
      { heading: 'Follow through', permission: 'trade-shows.leads.write', paragraphs: ["Route a lead to BIXOLON Sales when a rep should follow up. New imports or routing and assignment changes create or update the Sales follow-up Task. The usual due date is two business days, unless an Admin changes that setting. Older unchanged leads aren’t automatically given a Task.", "Use the Task to track the next action and the lead to keep the customer context current. Completing the Task doesn’t change lead status or log an Activity. Record the conversation separately when it happens."] },
      { heading: 'Source and campaign', paragraphs: ["Lead Source explains where the relationship started; a Campaign identifies the event or initiative. Linking an event lead can fill a Contact’s blank Lead Source without replacing an existing one. Campaign touches show interactions over time; they don’t assign revenue credit."] },
    ],
  },
  'marketing-attribution': {
    title: 'Marketing source & campaigns', group: 'Marketing', summary: 'Keep first touch distinct from later campaign interactions.', permission: 'marketing.read',
    sections: [
      { heading: 'First touch and later touches', paragraphs: ["Lead Source describes the original source. A Marketing Campaign is a named event or initiative. Campaign Influence records a dated interaction, so someone can have several campaign touches while keeping their original Lead Source.", "Use attribution and lead source reports to review the information recorded today. Campaign touches don’t assign revenue credit. An Opportunity may show different sources from its event lead and linked Contacts; don’t assume they all started in the same place."] },
      { heading: 'Correcting a source', permission: 'marketing.write', paragraphs: ["If a first-touch source is wrong, correct it with a reason rather than adding an unrelated campaign touch to compensate. Historical campaign touches remain available when a Campaign is archived."] },
    ],
  },
  'data-quality': {
    title: 'Data Quality', group: 'Administration', summary: 'Review likely problems and correct the records that need attention.', permission: 'users.manage',
    sections: [{ heading: 'Use the lists as a review queue', paragraphs: ["Start here when customer records, ownership, or pricing links need cleanup. Open a check, review the records, and follow the links to make the appropriate correction. A count is a reason to check, not proof that every listed record is wrong.", "The same record may appear in more than one group. Check the customer context before changing it, especially where a name could refer to more than one company."] }, { heading: 'Assign owners together', paragraphs: ["Admins can assign an owner to Accounts without a sales owner and Open Opportunities without an owner. Admins can also bulk reassign Accounts assigned to unavailable owners: users who are inactive, archived, or no longer have permission to manage Sales Accounts.", "Select up to 20 records on the current page, choose an eligible owner, then select Assign owner or Reassign owner and confirm. Select page selects only that page; changing the search or page clears the selection. If a selected record changed or an owner is no longer eligible, nothing changes. Success refreshes the counts and appears in Maintenance History. Contacts continue to use their Account’s owner.", "All other checks require individual review, including duplicates, missing relationships or expected close dates, and inactive or archived relationships. Use Open record to review them."] }],
  },
  'ownership-reassignment': {
    title: 'Ownership & Reassignment', group: 'Administration', summary: 'Hand active work to someone who can take it forward.', permission: 'users.manage',
    sections: [{ heading: 'When responsibilities change', paragraphs: ["Use Ownership & Reassignment when someone changes roles, leaves the company, or active records are still assigned to an inactive user. Filter by record type and current user, then review who should take over. Contacts use their Account’s owner.", "Tasks and Support Cases offer confirmed bulk reassignment for up to 20 selected records on the current page. Review your selection and confirm the new assignee before applying the change. Other records link to their individual edit forms.", "This page focuses on current work with an unsuitable owner; use Data Quality to review unowned Accounts and Opportunities or bulk reassign Accounts owned by unavailable users. Clear filters keeps the selected record type and removes the user filter."] }, { heading: 'Which records are included?', paragraphs: ["Completed work is excluded. Accounts must be active and unarchived. Contacts must be active and unarchived, with an active, unarchived Account. Opportunities must be open and unarchived. Projects must be unarchived and Planning, Active, or On Hold.", "Opportunities, Projects, and open Tasks also exclude links to inactive or archived Accounts and archived Projects; Tasks include Open and In Progress. Support Cases are checked separately: they must be unarchived and neither Closed nor Resolved. Unassigned records do not appear in this reassignment list."] }],
  },
  'currency-settings': {
    title: 'Manage currencies', group: 'Administration', summary: 'Choose currencies for new entries without changing existing amounts.', permission: 'users.manage',
    sections: [
      { heading: 'Default and active currencies', paragraphs: ["Open Administration → Currency Settings to add or activate a supported currency. The default currency is used for new entries. To deactivate the default, activate another currency and make it the default first.", "Changing the default leaves existing amounts and currencies unchanged. SalesHub does not convert currencies. Inactive currencies remain readable on existing records and in history; use an active currency for new work."] },
      { heading: 'Why a currency selector may be hidden', paragraphs: ["When there is only one meaningful currency choice, SalesHub can hide the selector. Historical reports still show separate currencies when needed. Check the currency shown with totals before comparing or adding values."] },
    ],
  },
  'manage-choices': {
    title: 'Manage choices and stages', group: 'Administration', summary: 'Keep business choices clear while preserving existing records.', permission: 'users.manage',
    sections: [
      { heading: 'Add or retire a choice', paragraphs: ["Use Administration to manage Industries, Territories, Activity Types, Product Categories, competitors, outcome reasons, and Support Case categories. Add the name users should see. Lower display order numbers appear first.", "Inactive choices remain visible where they were already used. Codes are stable references used by imports and cannot be changed after creation. Active and Inactive control availability; archiving a customer or other record is a separate action."] },
      { heading: 'Outcome reasons and stages', paragraphs: ["An outcome reason explains why an Opportunity was won or lost. Applies to identifies Closed Won or Closed Lost. Renaming or retiring a reason preserves recorded outcome names and history.", "A sales stage describes progress and may mark a deal closed or won. Review those settings carefully before saving; changing a stage can affect how existing Opportunities appear in pipeline and reports. Display order only controls the order of choices."] },
      { heading: 'Labels and Support setup', paragraphs: ["Labels & Terminology changes display labels only in screens that support customization. It does not rename saved values or web addresses. Support Case Categories controls Case choices; System Health shows recorded mailbox connection status. Ask the system administrator to complete mailbox setup before connecting Gmail."] },
    ],
  },
  'system-health': {
    title: 'System Health', group: 'Administration', summary: 'Check recorded service and connection status when something seems delayed.', permission: 'users.manage',
    sections: [{ heading: 'Check what SalesHub has observed', paragraphs: ["Use System Health to check database, file storage, recorded scheduled jobs, Calendar connections, and Support Gmail status. If notifications or Calendar updates seem delayed, look for failed or stale checks and the latest recorded times.", "A connection marked Connected doesn’t prove that the next request will succeed. Missing or old evidence needs investigation; it isn’t a clean bill of health. The Integration & Job History section shows stored successes and unresolved failures from real actions. Open Review history for safe failure details and recovery evidence. Use the relevant integration page for connection settings."] }],
  },
  'audit-history': {
    title: 'Audit History', group: 'Administration', summary: 'Check who changed something and the values recorded at the time.', permission: 'users.manage',
    sections: [{ heading: 'Investigate a change', paragraphs: ["Use Audit History when you need to understand a recorded change, such as an Opportunity’s owner or a Case’s priority. Filter by date, person, record type, or action, then open the record for context. Previous and new values appear where they were recorded. On smaller screens, open Filters to choose a date, person, record type, or change type, then select Apply filters. Clear filters returns to this history view without those filters.", "Coverage depends on the type of record and change. Not recorded means SalesHub doesn’t have that detail; don’t treat it as proof that nothing changed. This isn’t a complete history of every field on every page. From and Through dates include whole UTC days; displayed times use Eastern time. An event near midnight can display on a different Eastern date."] }],
  },
  'maintenance-history': {
    title: 'Maintenance History', group: 'Administration', summary: 'Review recorded cleanup, import, archive, and bulk work.', permission: 'users.manage',
    sections: [{ heading: 'Review a larger action', paragraphs: ["Use Maintenance History to check supported cleanup actions, confirmed imports, archive or restore work, and bulk changes. Entries show who acted, when, what kind of work was done, and how many records were affected. Open individual record links for context.", "Only supported actions are recorded here; older work isn’t filled in afterward. Use Audit History or the record’s own history for recorded field changes. Open Integration & Job History for Gmail actions, Calendar syncs and weekly snapshot attempts. Filter by integration, status, date or actor. Recovered means a later matching operation succeeded; a reconnect alone does not recover a failed action. History is available from when SalesHub began recording each action. Maintenance History is a review page, with no editing controls."] }],
  },
  'bulk-actions': {
    title: 'Bulk Actions', group: 'Getting Started', summary: 'Review a small selection before applying the same change.', permission: 'support-work.write',
    sections: [
      { heading: 'Select, review, confirm', paragraphs: ["Use Bulk Actions when the same supported change applies to several records. Select up to 20 records on the current page. Review the selected records and the proposed change before confirming; selecting a page doesn’t select every matching result.", "If a record changed while you were reviewing, or one needs a correction, the selection won’t be partly applied. Refresh, review the affected record, and try again."] },
      { heading: 'Tasks', permission: 'tasks.write', paragraphs: ["On Tasks, you can complete selected Tasks, reassign them, or set a due date. Choose the same change only when it makes sense for every selected Task."] },
      { heading: 'Support Cases', permission: 'support-cases.write', paragraphs: ["On Support Cases, you can reassign selected Cases or change priority. Status changes still need individual review."] },
      { heading: 'Other cleanup tools', permission: 'users.manage', paragraphs: ["Price Exception Cleanup has its own confirmed actions. Review those selections separately. Bulk Actions doesn’t provide a general way to delete records or rewrite customer relationships."] },
    ],
  },
} satisfies Record<string, HelpTopic>;

export type HelpTopicId = keyof typeof helpTopics;
export function visibleHelpTopics(actor: Actor) {
  if (routeAccess('/', actor) !== 'allowed') return [];
  return (Object.entries(helpTopics) as [HelpTopicId, HelpTopic][])
    .filter(([, topic]) => (!topic.permission || can(actor, topic.permission)) && (!topic.accessPath || routeAccess(topic.accessPath, actor) === 'allowed'))
    .map(([id, topic]) => ({ id, ...topic, sections: topic.sections.filter(section => !section.permission || can(actor, section.permission)) }));
}
